// models.ts — the game's component-model ATLAS (viewer/models/, generated by
// tools/extract_models.py): typed manifest + lazy per-type geometry. PURE
// types + a fetch loader (no THREE); scene.ts turns ModelGeo into meshes.
//
// The manifest is the PLACEMENT TRUTH (the .ini node tree — NOT the glTF
// node translations, which are Blender authoring offsets). Geometry prims
// carry the full vertex list `v`/index `i` AND the quantized+welded
// decimated twin `lv`/`li` (the default display; the full mesh is the
// "real models" hi-def path, a later REWRITE phase).

import type { BlueprintComponent } from './format';

/** LINEAR baseColorFactor-style entry from the glTF (metal/rough 0..1). */
export interface MatEntry {
  color: number[];
  metal?: number;
  rough?: number;
  /** 'BLEND' ⇒ alpha-blended, color[3] is the alpha */
  alpha?: string;
}

/** A node of the .ini tree (RENDERABLE/JOINT/TARGET share the shape). */
export interface NodeRec {
  name: string;
  parent?: string;
  position: [number, number, number];
  /** DEGREES, applied in ZYX order like the game engine */
  rotation: [number, number, number];
}

export interface JointRec extends NodeRec {
  /** spin axis: the .ini angular_x/y/z key → 'x'|'y'|'z' */
  axis?: 'x' | 'y' | 'z';
  /** slide axis: the .ini linear_x/y/z key */
  slide?: 'x' | 'y' | 'z';
  limits?: [number, number, number] | null;
}

export interface AdapterRec {
  name: string;
  type: string;
  position: [number, number, number];
  rotation: [number, number, number];
}

export interface ColliderRec {
  name: string;
  parent?: string;
  min: [number, number, number];
  max: [number, number, number];
}

export interface ModelInfo {
  module: string;
  mass: number;
  renderables: NodeRec[];
  joints: JointRec[];
  targets: NodeRec[];
  adapters: AdapterRec[];
  colliders: ColliderRec[];
  materials: Record<string, MatEntry>;
}

export type ModelManifest = Readonly<Record<string, ModelInfo>>;

export interface Prim {
  material: string;
  /** full vertex list, flat xyz (raw LH local space) */
  v: number[];
  /** full triangle index list */
  i: number[];
  /** decimated twin (quantized+welded, extract_models lowify) */
  lv?: number[];
  li?: number[];
}

export interface NodeGeo { prims: Prim[]; translation?: number[] }

/** per renderable-node geometry, keyed by .ini node name */
export type ModelGeo = Readonly<Record<string, NodeGeo>>;

export interface LoadedModel { geo: ModelGeo; info: ModelInfo }

/** What the engine needs to place and shade components (injected so tests
 *  and offline runs can pass null — unknown types keep the stand-in box). */
export interface ModelAtlas {
  readonly manifest: ModelManifest;
  /** lazy per-type geometry load; null once known-missing (never throws) */
  geoFor(type: string): Promise<LoadedModel | null>;
}

const BASE = '/models';

let manifestP: Promise<ModelManifest | null> | null = null;
export function loadManifest(): Promise<ModelManifest | null> {
  return manifestP ??= fetch(`${BASE}/manifest.json`)
    .then(r => (r.ok ? r.json() as Promise<ModelManifest> : null))
    .catch(() => null);
}

export function openAtlas(): Promise<ModelAtlas | null> {
  return loadManifest().then(m => (m ? { manifest: m, geoFor } : null));
}

const cache = new Map<string, Promise<LoadedModel | null>>();

/** lazy <Type>.json fetch, memoised per type (atlas files are immutable) */
export function geoFor(type: string): Promise<LoadedModel | null> {
  if (!cache.has(type)) {
    cache.set(type, loadManifest().then(async m => {
      const info = m?.[type];
      if (!info) return null;
      const r = await fetch(`${BASE}/${type}.json`).catch(() => null);
      return r && r.ok ? { geo: bakeGeo(type, await r.json() as ModelGeo), info } : null;
    }).catch(() => null));
  }
  return cache.get(type)!;
}

// ---------- per-asset VERTEX SPACE (tools/asset_space.py, 2026-10-19) ----------
// The game's glTF loader bakes the Blender/Z-up author space into the Unity
// part frame as (gx, -gz, gy) for MOST assets (its import setting "Bake Axis
// Conversion"); a minority ship already Y-up (Blender zero-rot exports whose
// .ini colliders only fit the raw verts). XenonViewer places every asset
// under a C=(x,z,-y)-transformed .ini node chain; the file-frame equivalent
// for the baked majority is: bake (x,-z,y) = Rx(+90) into the vertices and
// keep the RAW .ini chain (algebra: C·chain·C⁻¹·v = chain·(C⁻¹·v)).
// UNITY_BAKED_TYPES = the majority, classified offline against each part's
// [COLLIDER] box in its .ini (position+euler applied): strictly-better fit
// by >= 0.15 m summed; ties default RAW (the pre-fix look) so symmetric
// parts (wheels, Beacon) never flip silently — v0.145's GLOBAL bake flipped
// the y-up assets and was reverted (AGENTS §Known open issues). RE-RUN
// `python3 tools/asset_space.py` after game updates (same ritual as
// DROP_TABLE) and keep FORMAT.md §Per-asset gltf loader conventions in sync.

export const UNITY_BAKED_TYPES: ReadonlySet<string> = new Set([
  'ActiveRadiator', 'Aileron', 'ChemicalFurnace', 'ChemicalReactor', 'Computer',
  'Crafter', 'Dashboard', 'DataJunction', 'DockableDoor', 'EnrichmentCentrifuge',
  'GeothermalExchanger', 'GroundAnchor', 'HighVoltageJunction', 'Lamp',
  'LowVoltageJunction', 'LowVoltageRelay', 'MiniComputer', 'MiniRouter',
  'OreScanner', 'OwnerPad', 'PassiveRadiator', 'PilotSeat', 'RTG', 'Router',
  'SabatierReactor', 'SmallHinge', 'SmallTurboPump', 'SolarPanel', 'Step',
  'TerrainScanner', 'TrashCan', 'Volume',
]);

/** Rx(+90): Blender/glTF Z-up author space -> the game's Y-up part frame */
export function unityBake(v: number[]): number[] {
  const out = new Array<number>(v.length);
  for (let i = 0; i < v.length; i += 3) {
    out[i] = v[i]!; out[i + 1] = -v[i + 2]!; out[i + 2] = v[i + 1]!;
  }
  return out;
}

/** per-type vertex-space fix applied to the atlas JSON once at load */
function bakeGeo(type: string, geo: ModelGeo): ModelGeo {
  if (!UNITY_BAKED_TYPES.has(type)) return geo;
  const out: Record<string, NodeGeo> = {};
  for (const [name, nd] of Object.entries(geo))
    out[name] = { ...nd, prims: nd.prims.map(p => ({
      ...p, v: unityBake(p.v), ...(p.lv ? { lv: unityBake(p.lv) } : {}),
    })) };
  return out;
}

// ---------- conditional parts (client behaviour, XenonViewer parity) ----------
// Renderables the game shows only under a condition: a wheel gltf carries
// BOTH tire toruses (data.reverse picks one) and an optional mudguard; a
// ToggleButton has two lever states. Rendering all of them stacks a double
// tire / a phantom lever through the mount.

interface ConditionalData {
  mudguard?: boolean;
  reverse?: boolean;
  state?: boolean;
  isDualSided?: boolean;
}

type DropList = (string | null)[];
const DROP_TABLE: Readonly<Record<string, (d: ConditionalData) => DropList>> = {
  Wheel: d => [...(d.mudguard === false ? ['mudguard'] : []), d.reverse ? 'Torus' : 'TorusReverse'],
  BigWheel: d => [d.reverse ? 'Torus' : 'TorusReverse'],
  ToggleButton: d => [d.state ? 'switch2' : 'switch', d.isDualSided ? null : 'base2'],
  PushButton: d => [d.isDualSided ? null : 'base2'],
};

/** renderable-node names this component must NOT render */
export function droppedParts(c: BlueprintComponent): ReadonlySet<string> {
  const f = DROP_TABLE[c.type];
  if (!f) return new Set();
  const d = (c.data ?? {}) as ConditionalData;
  return new Set(f(d).filter((n): n is string => n != null));
}

